CREATE TABLE dbo.app_settings (key_name nvarchar(80) NOT NULL PRIMARY KEY, value nvarchar(2000) NOT NULL);
CREATE TABLE dbo.tabela_materijala (Id int IDENTITY PRIMARY KEY,ident int NOT NULL UNIQUE,nazmat nvarchar(220) NOT NULL,jedm nvarchar(12) NOT NULL,siftar int NULL,konto1 int NULL,konto2 nvarchar(50) NULL);
GO
CREATE VIEW dbo.sifarnik_materijala AS SELECT Id,ident,nazmat,jedm,siftar,konto1,konto2 FROM dbo.tabela_materijala;
GO
CREATE TABLE dbo.sifarnik_skladista (id int IDENTITY PRIMARY KEY,kljnaz int NOT NULL UNIQUE,naziv_org nvarchar(100) NOT NULL,ziro_racun nvarchar(40) NULL,poz_br nvarchar(40) NULL,devizni_racun nvarchar(40) NULL,poz_br_d nvarchar(40) NULL,opstina nvarchar(50) NULL,naziv_sdk nvarchar(50) NULL,mjesto_adresa nvarchar(100) NULL);
CREATE TABLE dbo.sifarnik_konta (id int IDENTITY PRIMARY KEY,sifkonta int NOT NULL UNIQUE,nazkont nvarchar(220) NOT NULL,stakont int NULL,stamt int NULL);
CREATE TABLE dbo.sifarnik_materijal_skladiste_konto (Id int IDENTITY PRIMARY KEY,Sifmat int NOT NULL,Sifskla int NOT NULL,Sifkonta int NOT NULL,CONSTRAINT UQ_material_warehouse UNIQUE(Sifmat,Sifskla),CONSTRAINT FK_link_material FOREIGN KEY(Sifmat) REFERENCES dbo.tabela_materijala(ident),CONSTRAINT FK_link_warehouse FOREIGN KEY(Sifskla) REFERENCES dbo.sifarnik_skladista(kljnaz),CONSTRAINT FK_link_account FOREIGN KEY(Sifkonta) REFERENCES dbo.sifarnik_konta(sifkonta));
CREATE TABLE dbo.material_document (id uniqueidentifier NOT NULL PRIMARY KEY,status nvarchar(1) NOT NULL,book_year int NOT NULL,number nvarchar(50) NOT NULL,warehouse int NOT NULL,created_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT UQ_document UNIQUE(status,book_year,number,warehouse));
CREATE TABLE dbo.document_counter (name nvarchar(80) NOT NULL,book_year int NOT NULL,last_number int NOT NULL,CONSTRAINT PK_document_counter PRIMARY KEY(name,book_year));
CREATE TABLE dbo.mat (
id int IDENTITY PRIMARY KEY, kljnaz int NULL, kljnaz1 int NULL, ident int NULL, datun datetime NULL, analst nvarchar(50) NULL, brdok nvarchar(100) NULL, brnar nvarchar(100) NULL, datnar datetime NULL, brfak nvarchar(50) NULL,
kolic decimal(18,2) NULL,nc decimal(17,9) NULL,vrijed decimal(18,2) NULL,redbr int NULL,status nvarchar(1) NULL,konto1 int NULL,konto2 nvarchar(50) NULL,fcj nvarchar(50) NULL,troskovi decimal(18,2) NULL,cartro nvarchar(50) NULL,zavtro nvarchar(50) NULL,ppp nvarchar(50) NULL,tarifa nvarchar(10) NULL,fvrijed nvarchar(50) NULL,porppp decimal(18,2) NULL,medus nvarchar(1) NULL,kontosklad int NULL,kontosklad1 int NULL,trospe decimal(18,2) NULL,ourst int NULL,mjtst int NULL,
is_draft bit NOT NULL DEFAULT 1,is_archived bit NOT NULL DEFAULT 0,book_year int NOT NULL,document_id uniqueidentifier NULL,transfer_pair_id uniqueidentifier NULL,line_token uniqueidentifier NOT NULL DEFAULT NEWID(),fox_recno int NULL,row_version rowversion NOT NULL,
CONSTRAINT FK_mat_material FOREIGN KEY(ident) REFERENCES dbo.tabela_materijala(ident),CONSTRAINT FK_mat_warehouse FOREIGN KEY(kljnaz) REFERENCES dbo.sifarnik_skladista(kljnaz),CONSTRAINT FK_mat_destination FOREIGN KEY(kljnaz1) REFERENCES dbo.sifarnik_skladista(kljnaz),CONSTRAINT FK_mat_document FOREIGN KEY(document_id) REFERENCES dbo.material_document(id),
CONSTRAINT CK_mat_posted CHECK(is_draft=1 OR (ident>0 AND kljnaz>0 AND datun IS NOT NULL AND kolic IS NOT NULL AND nc>=0 AND vrijed IS NOT NULL AND status IN ('P','U','I','M','V'))),
CONSTRAINT CK_mat_sign CHECK(is_draft=1 OR (status IN ('U','V') AND kolic>0 AND vrijed>=0) OR (status='P' AND kolic>=0 AND vrijed>=0) OR (status='I' AND kolic<0 AND vrijed<=0) OR (status='M' AND ((kolic>0 AND vrijed>=0) OR (kolic<0 AND vrijed<=0))))
);
CREATE UNIQUE INDEX UQ_mat_line_token ON dbo.mat(line_token);
CREATE INDEX IX_mat_stock ON dbo.mat(book_year,kljnaz,ident,is_draft,is_archived) INCLUDE(kolic,vrijed,nc,status,datun);
CREATE INDEX IX_mat_document ON dbo.mat(document_id,is_draft);
CREATE INDEX IX_mat_transfer_pair ON dbo.mat(transfer_pair_id) WHERE transfer_pair_id IS NOT NULL;
CREATE TABLE dbo.inv (
id int IDENTITY PRIMARY KEY,kljnaz int NULL,ident int NULL,datun datetime NULL,analst nvarchar(50) NULL,brdok nvarchar(100) NULL,brnar nvarchar(100) NULL,datnar datetime NULL,brfak nvarchar(50) NULL,kolic decimal(18,2) NULL,nc decimal(17,9) NULL,vrijed decimal(18,2) NULL,redbr int NULL,status nvarchar(1) NULL,konto1 int NULL,konto2 nvarchar(50) NULL,fcj nvarchar(50) NULL,troskovi decimal(18,2) NULL,cartro nvarchar(50) NULL,zavtro nvarchar(50) NULL,ppp nvarchar(50) NULL,tarifa nvarchar(10) NULL,fvrijed nvarchar(50) NULL,porppp decimal(18,2) NULL,kontosklad int NULL,kontosklad1 int NULL,trospe decimal(18,2) NULL,ourst int NULL,mjtst int NULL,
is_draft bit NOT NULL DEFAULT 1,is_archived bit NOT NULL DEFAULT 0,inventory_date date NULL,inventory_session_id uniqueidentifier NULL,fox_recno int NULL,row_version rowversion NOT NULL,
CONSTRAINT FK_inv_material FOREIGN KEY(ident) REFERENCES dbo.tabela_materijala(ident),CONSTRAINT FK_inv_warehouse FOREIGN KEY(kljnaz) REFERENCES dbo.sifarnik_skladista(kljnaz));
CREATE UNIQUE INDEX UQ_inventory_line ON dbo.inv(inventory_session_id,kljnaz,ident) WHERE is_draft=0 AND is_archived=0 AND inventory_session_id IS NOT NULL;
CREATE TABLE dbo.financial_batch (id uniqueidentifier NOT NULL PRIMARY KEY,source_document_id uniqueidentifier NULL,source_status nvarchar(1) NOT NULL,brfak nvarchar(50) NOT NULL,activity int NOT NULL,book_year int NOT NULL,number int NOT NULL,document_date datetime NOT NULL,state nvarchar(20) NOT NULL,content_hash nvarchar(64) NOT NULL,error nvarchar(2000) NULL,attempt_count int NOT NULL DEFAULT 0,created_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),exported_at datetime2 NULL,row_version rowversion NOT NULL,CONSTRAINT FK_batch_document FOREIGN KEY(source_document_id) REFERENCES dbo.material_document(id));
CREATE UNIQUE INDEX UQ_batch_source ON dbo.financial_batch(source_document_id) WHERE source_document_id IS NOT NULL;
CREATE UNIQUE INDEX UQ_batch_number ON dbo.financial_batch(activity,number,document_date);
CREATE TABLE dbo.nalmat (id int IDENTITY PRIMARY KEY,rostav int NOT NULL,datnsta datetime NOT NULL,sifakt int NOT NULL,bronsta int NOT NULL,sintstav int NOT NULL,brdokst nvarchar(100) NOT NULL,kukistav int NOT NULL,datdokst datetime NOT NULL,devsta nvarchar(10) NULL,kurs decimal(18,4) NULL,datvalst nvarchar(50) NOT NULL,ourst int NULL,mjtst int NULL,analst nvarchar(50) NULL,dug1st decimal(18,2) NULL,stodug1 decimal(18,2) NULL,pot1st decimal(18,2) NULL,stopot1 decimal(18,2) NULL,devdugst decimal(18,2) NULL,stodevd decimal(18,2) NULL,devpotst decimal(18,2) NULL,stodevp decimal(18,2) NULL,bracuna nvarchar(100) NULL,brfak nvarchar(50) NULL,line_number int NULL,batch_id uniqueidentifier NULL,fox_recno int NULL,CONSTRAINT FK_nalmat_batch FOREIGN KEY(batch_id) REFERENCES dbo.financial_batch(id));
CREATE INDEX IX_nalmat_document ON dbo.nalmat(brfak,sifakt,datnsta);
CREATE TABLE dbo.financial_export_log (id bigint IDENTITY PRIMARY KEY,batch_id uniqueidentifier NOT NULL,created_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),state nvarchar(20) NOT NULL,error nvarchar(2000) NULL,CONSTRAINT FK_export_log_batch FOREIGN KEY(batch_id) REFERENCES dbo.financial_batch(id));
CREATE TABLE dbo.year_close (id int IDENTITY PRIMARY KEY,book_year int NOT NULL UNIQUE,next_year int NOT NULL,created_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),source nvarchar(20) NOT NULL,quantity decimal(38,2) NOT NULL,value decimal(38,2) NOT NULL);
CREATE TABLE dbo.fox_import_manifest (table_name nvarchar(50) PRIMARY KEY,physical_rows int NOT NULL,active_rows int NOT NULL,source_hash nvarchar(64) NOT NULL,imported_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
